define('admin-tools-purge-messages', {
  prefix: 'adminTools.purge.js.',
  keys: [
    'saving',
    'saved',
    'loading',
    'loadFailed',
    'nothingExpired',
    'expired',
    'expiredOne',
    'expiredVersions',
    'expiredVersionOne',
    'nothingToPurge',
    'nothingToPurge.type',
    'error.400',
    'error.401',
    'error.402',
    'error.403',
    'error.404',
    'error.generic',
    'error.number',
    'error.noLimit'
  ]
});

require(['jquery', 'xwiki-l10n!admin-tools-purge-messages', 'bootstrap'], function($, l10n) {
  'use strict';

  const types = ['deletedDocuments', 'deletedAttachments', 'pageHistory'];
  // A history can also be limited by a number of versions, and needs an age limit, a number of versions, or both. Its
  // versions are counted only when a purge is submitted, since counting them is costly.
  const historyTypes = ['pageHistory'];
  const isHistory = type => historyTypes.includes(type);
  const restURL = XWiki.contextPath + '/rest/admintools/autopurge';
  const jsonURL = new XWiki.Document(XWiki.Model.resolve('AdminTools.Purge.Code.PurgeJSON',
    XWiki.EntityType.DOCUMENT)).getURL('get');
  // While the history shows a purge in progress, it is refreshed more and more rarely, and no longer after a few
  // minutes: a purge of one wiki shouldn't take that long, and the history can still be refreshed manually. In
  // milliseconds.
  const minRefreshDelay = 2000;
  const maxRefreshDelay = 10000;
  const maxRefreshDuration = 5 * 60 * 1000;

  const getErrorMessage = function(xhr) {
    return l10n.get([400, 401, 402, 403, 404].includes(xhr.status) ? 'error.' + xhr.status : 'error.generic');
  };

  /**
   * Send a request changing the automatic purge, and report its progress and outcome when messages are given. Errors
   * are always reported. XWiki adds the form token expected by the REST resource to the headers of the request.
   */
  const send = function(method, path, data, progressMessage, successMessage) {
    const notification = progressMessage ? new XWiki.widgets.Notification(progressMessage, 'inprogress') : null;
    return $.ajax({
      url: restURL + path,
      type: method,
      data: data,
      traditional: true
    }).done(function() {
      if (notification && successMessage) {
        notification.replace(new XWiki.widgets.Notification(successMessage, 'done'));
      } else if (notification) {
        notification.hide();
      }
    }).fail(function(xhr) {
      const error = new XWiki.widgets.Notification(getErrorMessage(xhr), 'error');
      if (notification) {
        notification.replace(error);
      }
    });
  };

  const post = function(path, data, progressMessage, successMessage) {
    return send('POST', path, data, progressMessage, successMessage);
  };

  const getTypeContainer = function(form, type) {
    return form.find('.purge-type[data-type="' + type + '"]');
  };

  const getWikiPath = function(wikiId) {
    return '/wikis/' + encodeURIComponent(wikiId);
  };

  const refreshLiveData = function(id) {
    const liveData = $('#' + id).data('liveData');
    if (liveData) {
      liveData.updateEntries();
    }
  };

  /**
   * Add the limit of an enabled item type to the submitted data: its interval and unit, and for a history, its number
   * of versions. They are left out for an item type that is not enabled, which keeps its stored ones for when it is
   * enabled again, and for a limit of a history that is left empty, which then doesn't apply.
   */
  const addLimit = function(data, typeContainer, type) {
    const interval = getNumber(typeContainer.find('.purge-interval'));
    if (interval) {
      data[type + 'Interval'] = interval;
      data[type + 'Unit'] = typeContainer.find('.purge-unit').val();
    }
    const maxVersions = isHistory(type) ? getNumber(typeContainer.find('.purge-max-versions')) : null;
    if (maxVersions) {
      data[type + 'MaxVersions'] = maxVersions;
    }
  };

  /**
   * Get the value of a number field, if it is set and valid.
   */
  const getNumber = function(input) {
    return input.val() === '' || getNumberError(input) ? null : input.val();
  };

  /**
   * Check a number field against its `min` and `max` attributes. An empty field is valid if it is not required.
   *
   * @return the translated error message, or `null` if the value is valid
   */
  const getNumberError = function(input) {
    const value = input.val();
    if (value === '' && !input.prop('required')) {
      return null;
    }
    const min = parseInt(input.attr('min'), 10);
    const max = parseInt(input.attr('max'), 10);
    if (!/^\d+$/.test(value) || parseInt(value, 10) < min || parseInt(value, 10) > max) {
      return l10n.get('error.number', min, max);
    }
    return null;
  };

  /**
   * Check number fields, and show a translated message under each invalid one. The validation of the browser is not
   * used, since its messages follow the language of the browser instead of the language of the wiki.
   *
   * @return `true` if all the fields are valid
   */
  const validateNumbers = function(inputs) {
    inputs.each(function() {
      const input = $(this);
      const error = getNumberError(input);
      // The message goes under the fields of the limit, or under the field itself. The fields of a history hold two
      // numbers, so each message is removed only by the check of its own field.
      const fields = input.closest('.purge-interval-fields');
      const messageAnchor = fields.length ? fields : input;
      messageAnchor.nextAll('.purge-error').filter((index, message) => $(message).data('input') === this.id).remove();
      input.attr('aria-invalid', error ? 'true' : 'false');
      if (error) {
        $('<span class="help-block purge-error">').data('input', this.id).text(error).insertAfter(messageAnchor);
      }
      const formGroup = input.closest('.form-group');
      formGroup.toggleClass('has-error', formGroup.find('.purge-error').length > 0);
    });
    const invalidInputs = inputs.filter('[aria-invalid="true"]');
    invalidInputs.first().trigger('focus');
    return invalidInputs.length === 0;
  };

  /**
   * Check that the enabled limits of the given item types that are histories have an age limit, a number of versions,
   * or both, and show a translated message under the fields of each history without a limit.
   *
   * @return `true` if every history has a limit
   */
  const validateHistoryLimits = function(typeContainers) {
    let valid = true;
    typeContainers.filter((index, typeContainer) => isHistory($(typeContainer).data('type'))).each(function() {
      const typeContainer = $(this);
      typeContainer.find('.purge-limit-error').remove();
      const inputs = typeContainer.find('.purge-interval:enabled, .purge-max-versions:enabled');
      if (inputs.length && inputs.get().every(input => input.value === '')) {
        valid = false;
        typeContainer.addClass('has-error');
        $('<span class="help-block purge-error purge-limit-error">').text(l10n.get('error.noLimit'))
          .insertAfter(typeContainer.find('.purge-history-limits'));
      }
    });
    return valid;
  };

  /**
   * Check the enabled limits of the given item types: their numbers, and that each history has a limit.
   *
   * @return `true` if the limits are valid
   */
  const validateLimits = function(typeContainers) {
    // Both checks run, so that all the errors are shown.
    const numbersValid = validateNumbers(typeContainers.find('input[type="number"]:enabled'));
    return validateHistoryLimits(typeContainers) && numbersValid;
  };

  /**
   * Remove the messages of a previous validation, when a modal opens or when the fields of an item type are disabled,
   * since a disabled field is neither checked nor saved.
   */
  const clearErrors = function(container) {
    container.find('.purge-error').remove();
    container.find('.has-error').addBack('.has-error').removeClass('has-error');
    container.find('[aria-invalid]').removeAttr('aria-invalid');
  };

  $(document).on('show.bs.modal', '.purge-modal', function() {
    clearErrors($(this));
  });

  // A stored limit can only be invalid after a manual edit: its error is shown as soon as the settings are opened.
  $(document).on('shown.bs.modal', '#purgeDefaultsModal, #purgeWikiModal', function() {
    validateNumbers($(this).find('input[type="number"]:enabled'));
  });

  // The error of a setting is shown while it is typed, not only when the settings are saved. A missing limit is only
  // reported when the settings are saved, since a limit is often emptied before the other one is set.
  $(document).on('input', '#purgeDefaultsForm input[type="number"], #purgeWikiForm input[type="number"]', function() {
    $(this).closest('.purge-type').find('.purge-limit-error').remove();
    validateNumbers($(this));
  });

  // The default settings.
  const updateDefaultFields = function(typeContainer) {
    const enabled = typeContainer.find('.purge-enable').prop('checked');
    typeContainer.find('.purge-interval-fields :input').prop('disabled', !enabled);
    if (!enabled) {
      clearErrors(typeContainer);
    }
  };

  $(document).on('change', '#purgeDefaultsForm .purge-enable', function() {
    updateDefaultFields($(this).closest('.purge-type'));
  });

  const getDefaultsFormState = function(form) {
    const state = {maxHistoryEntries: form.find('[name="maxHistoryEntries"]').val()};
    types.forEach(type => {
      const typeContainer = getTypeContainer(form, type);
      state[type] = {
        enabled: typeContainer.find('.purge-enable').prop('checked'),
        interval: typeContainer.find('.purge-interval').val(),
        unit: typeContainer.find('.purge-unit').val(),
        maxVersions: typeContainer.find('.purge-max-versions').val()
      };
    });
    return state;
  };

  const setDefaultsFormState = function(form, state) {
    form.find('[name="maxHistoryEntries"]').val(state.maxHistoryEntries);
    types.forEach(type => {
      const typeContainer = getTypeContainer(form, type);
      typeContainer.find('.purge-enable').prop('checked', state[type].enabled);
      typeContainer.find('.purge-interval').val(state[type].interval);
      typeContainer.find('.purge-unit').val(state[type].unit);
      typeContainer.find('.purge-max-versions').val(state[type].maxVersions);
      updateDefaultFields(typeContainer);
    });
  };

  // The default settings as last saved, so that the changes of a cancelled edit are undone when the modal opens again.
  // The form holds them until it is first opened.
  let savedDefaults;
  $(document).on('show.bs.modal', '#purgeDefaultsModal', function() {
    const form = $(this).find('form');
    if (savedDefaults) {
      setDefaultsFormState(form, savedDefaults);
    } else {
      savedDefaults = getDefaultsFormState(form);
    }
  });

  $(document).on('submit', '#purgeDefaultsForm', function(event) {
    event.preventDefault();
    const form = $(this);
    // The fields of the item types that are not purged automatically are disabled, and not checked.
    const limitsValid = validateLimits(form.find('.purge-type'));
    if (!validateNumbers(form.find('[name="maxHistoryEntries"]')) || !limitsValid) {
      return;
    }
    const data = {maxHistoryEntries: form.find('[name="maxHistoryEntries"]').val()};
    types.forEach(type => {
      const typeContainer = getTypeContainer(form, type);
      const enabled = typeContainer.find('.purge-enable').prop('checked');
      data[type + 'Mode'] = enabled ? 'enabled' : 'disabled';
      if (enabled) {
        addLimit(data, typeContainer, type);
      }
    });
    const state = getDefaultsFormState(form);
    post('/settings', data, l10n.get('saving'), l10n.get('saved')).done(function() {
      savedDefaults = state;
      $('#purgeDefaultsModal').modal('hide');
      refreshDefaults();
      refreshLiveData('purgeWikis');
    });
  });

  /**
   * Update the summary of the default settings once they were saved.
   */
  const refreshDefaults = function() {
    $.getJSON(jsonURL, {data: 'defaults'}).done(function(summary) {
      Object.keys(summary).forEach(key => $('.purge-defaults-' + key).text(summary[key]));
    });
  };

  // The settings of a wiki.
  const setWikiName = function(modal, wikiName) {
    modal.data('wikiName', wikiName).find('.purge-wiki-name').text(wikiName);
  };

  const updateCustomFields = function(typeContainer) {
    const custom = typeContainer.find('.purge-mode:checked').val() === 'enabled';
    typeContainer.find('.purge-interval-fields :input').prop('disabled', !custom);
    if (!custom) {
      clearErrors(typeContainer);
    }
  };

  $(document).on('click', '.purge-edit', function() {
    const wiki = $(this).data('purge');
    const modal = $('#purgeWikiModal').data('wikiId', wiki.wikiId);
    setWikiName(modal, wiki.wikiName);
    types.forEach(type => {
      const settings = wiki.types[type];
      const typeContainer = getTypeContainer(modal, type);
      typeContainer.find('.purge-mode[value="' + settings.mode + '"]').prop('checked', true);
      typeContainer.find('.purge-default-label').text(settings.defaultLabel);
      typeContainer.find('.purge-interval').val(settings.interval);
      // An item type that is not enabled can have no stored unit: months is selected, as in the other forms.
      typeContainer.find('.purge-unit').val(settings.unit || 'months');
      typeContainer.find('.purge-max-versions').val(settings.maxVersions);
      updateCustomFields(typeContainer);
    });
    modal.modal('show');
  });

  $(document).on('change', '#purgeWikiForm .purge-mode', function() {
    updateCustomFields($(this).closest('.purge-type'));
  });

  // Save the settings of the wiki of the modal, or remove them (method DELETE) so that it uses the defaults.
  const updateWikiSettings = function(method, data) {
    const modal = $('#purgeWikiModal');
    send(method, getWikiPath(modal.data('wikiId')) + '/settings', data, l10n.get('saving'), l10n.get('saved'))
      .done(function() {
        modal.modal('hide');
        refreshLiveData('purgeWikis');
      });
  };

  $(document).on('submit', '#purgeWikiForm', function(event) {
    event.preventDefault();
    const form = $(this);
    // Only the custom limits are enabled, and checked.
    if (!validateLimits(form.find('.purge-type'))) {
      return;
    }
    const data = {};
    types.forEach(type => {
      const typeContainer = getTypeContainer(form, type);
      const mode = typeContainer.find('.purge-mode:checked').val();
      data[type + 'Mode'] = mode;
      if (mode === 'enabled') {
        addLimit(data, typeContainer, type);
      }
    });
    updateWikiSettings('POST', data);
  });

  $(document).on('click', '#purgeWikiForm .purge-reset', function() {
    updateWikiSettings('DELETE');
  });

  // The manual purge of a wiki.
  /**
   * Enable the purge button when a selected item type has items older than its limit, or is a history, whose versions
   * are counted once the purge is submitted.
   */
  const updatePurgeButton = function(form) {
    const canPurge = form.find('input[name="type"]:checked').closest('.purge-type').get()
      .some(typeContainer => isHistory($(typeContainer).data('type')) || $(typeContainer).data('count') > 0);
    form.find('button[type="submit"]').prop('disabled', !canPurge);
  };

  /**
   * Show how many items of an item type are past its limit, and remember it for the purge button.
   */
  const showCount = function(typeContainer, count) {
    let label = '';
    if (count === 0) {
      label = '(' + l10n.get('nothingExpired') + ')';
    } else if (count === 1) {
      label = '(' + l10n.get('expiredOne') + ')';
    } else if (count !== undefined) {
      label = '(' + l10n.get('expired', count) + ')';
    }
    typeContainer.find('.purge-count').text(label);
    // Not counted (undefined) is stored as 0, since data(key, undefined) would only read the stored count.
    typeContainer.data('count', count || 0);
  };

  // Only the response of the newest preview request is shown, and a request identical to the previous one is not sent.
  let previewRequest = 0;
  let previewParams;
  let previewTimeout;

  // A missing value is set as an empty field, since jQuery reads the field when the value is undefined.
  const orEmpty = value => value === undefined ? '' : value;

  const getPreviewURL = function(form) {
    return restURL + getWikiPath(form.closest('.modal').data('wikiId')) + '/preview';
  };

  /**
   * Count the items past the limit of each item type that is not a history. The first time, the limits are the stored
   * ones, which fill the fields of every item type; afterwards, they are the ones in the fields.
   */
  const updatePreview = function(form, fillFields) {
    const countedTypes = types.filter(type => !isHistory(type));
    const params = {type: countedTypes};
    if (!fillFields) {
      countedTypes.forEach(type => addLimit(params, getTypeContainer(form, type), type));
    }
    const paramsJSON = JSON.stringify(params);
    if (!fillFields && paramsJSON === previewParams) {
      return;
    }
    previewParams = paramsJSON;
    const requestNumber = ++previewRequest;
    countedTypes.forEach(type => getTypeContainer(form, type).find('.purge-count')
      .text('(' + l10n.get('loading') + ')'));
    $.ajax({url: getPreviewURL(form), data: params, dataType: 'json', traditional: true}).done(function(preview) {
      if (requestNumber !== previewRequest) {
        return;
      }
      types.forEach(type => {
        const typeContainer = getTypeContainer(form, type);
        const typePreview = preview[type];
        if (fillFields) {
          // A limit that is not stored leaves its field empty, and months is selected without a stored unit.
          typeContainer.find('.purge-interval').val(orEmpty(typePreview.interval));
          typeContainer.find('.purge-unit').val(typePreview.unit || 'months');
          typeContainer.find('.purge-max-versions').val(orEmpty(typePreview.maxVersions));
          typeContainer.find('.purge-disabled-note').toggleClass('hidden', typePreview.enabled);
        }
        if (!isHistory(type)) {
          // An invalid limit was not sent, so its count is the one of the stored limit.
          showCount(typeContainer, getNumber(typeContainer.find('.purge-interval')) ? typePreview.count : undefined);
        }
      });
      updatePurgeButton(form);
    }).fail(function(xhr) {
      if (requestNumber === previewRequest) {
        form.find('.purge-count').text('');
        new XWiki.widgets.Notification(getErrorMessage(xhr), 'error');
      }
    });
  };

  /**
   * Show the step selecting the item types and their limits, or the step confirming the purge.
   */
  const showPurgeStep = function(form, confirm) {
    form.find('.purge-step-select, button[type="submit"]').toggleClass('hidden', confirm);
    form.find('.purge-step-confirm, .purge-back, .purge-confirm').toggleClass('hidden', !confirm);
    form.find('.purge-confirm').prop('disabled', false);
  };

  $(document).on('click', '.purge-now', function() {
    // A preview still waiting for the modal of another wiki would replace the one of this wiki.
    clearTimeout(previewTimeout);
    const wiki = $(this).data('purge');
    const modal = $('#purgeNowModal').data({wikiId: wiki.wikiId, wiki: wiki});
    const form = modal.find('form');
    setWikiName(modal, wiki.wikiName);
    showPurgeStep(form, false);
    form.find('input[name="type"]').prop('checked', false);
    form.find('.purge-interval-fields :input').prop('disabled', true);
    form.find('.purge-type').removeData('count');
    form.find('.purge-count').text('');
    form.find('.purge-interval, .purge-max-versions').val('');
    form.find('.purge-disabled-note, .purge-nothing-started').addClass('hidden');
    updatePurgeButton(form);
    modal.modal('show');
    updatePreview(form, true);
  });

  // Count the items again once the user stops changing a limit. The versions of a history are counted on submit.
  $(document).on('input change', '#purgeNowForm input[type="number"], #purgeNowForm .purge-unit', function() {
    const form = $(this).closest('form');
    const typeContainer = $(this).closest('.purge-type');
    typeContainer.find('.purge-limit-error').remove();
    const valid = validateNumbers(typeContainer.find('input[type="number"]'));
    if (isHistory(typeContainer.data('type'))) {
      return;
    }
    clearTimeout(previewTimeout);
    // An invalid limit isn't counted, and its item type can't be purged until it is fixed.
    if (!valid) {
      showCount(typeContainer, undefined);
      updatePurgeButton(form);
      return;
    }
    previewTimeout = setTimeout(() => updatePreview(form, false), 400);
  });

  $(document).on('change', '#purgeNowForm input[name="type"]', function() {
    const typeContainer = $(this).closest('.purge-type');
    typeContainer.find('.purge-interval-fields :input').prop('disabled', !this.checked);
    if (!this.checked) {
      clearErrors(typeContainer);
    }
    updatePurgeButton($(this).closest('form'));
  });

  /**
   * @return the label of what the purge of an item type would remove
   */
  const getConfirmCountLabel = function(type, count) {
    if (count === 0) {
      return l10n.get('nothingToPurge.type');
    } else if (isHistory(type)) {
      return count === 1 ? l10n.get('expiredVersionOne') : l10n.get('expiredVersions', count);
    } else {
      return count === 1 ? l10n.get('expiredOne') : l10n.get('expired', count);
    }
  };

  // Count what the purge of each selected item type would remove, with its limit, then ask for a confirmation, unless
  // there is nothing to purge.
  $(document).on('submit', '#purgeNowForm', function(event) {
    event.preventDefault();
    const modal = $('#purgeNowModal');
    const form = $(this);
    const selectedTypes = form.find('input[name="type"]:checked').map((index, input) => input.value).get();
    // Only the limits of the selected item types are checked.
    if (!validateLimits(form.find('input[name="type"]:checked').closest('.purge-type'))) {
      return;
    }
    const data = {type: selectedTypes};
    selectedTypes.forEach(type => addLimit(data, getTypeContainer(form, type), type));
    form.find('.purge-nothing-started').addClass('hidden');
    form.find('button[type="submit"]').prop('disabled', true);
    const notification = new XWiki.widgets.Notification(l10n.get('loading'), 'inprogress');
    $.ajax({url: getPreviewURL(form), data: data, dataType: 'json', traditional: true}).done(function(preview) {
      notification.hide();
      // The server doesn't count the items again, so the item types with nothing to purge are left out.
      const typesToPurge = selectedTypes.filter(type => preview[type].count > 0);
      if (typesToPurge.length === 0) {
        new XWiki.widgets.Notification(l10n.get('nothingToPurge'), 'info');
        updatePurgeButton(form);
        return;
      }
      const counts = form.find('.purge-confirm-counts').empty();
      selectedTypes.forEach(type => {
        const typeLabel = getTypeContainer(form, type).find('.purge-type-label').text();
        counts.append($('<li>').append($('<strong>').text(typeLabel),
          document.createTextNode(': ' + getConfirmCountLabel(type, preview[type].count))));
      });
      modal.data('purgeData', Object.assign(data, {type: typesToPurge}));
      showPurgeStep(form, true);
    }).fail(function(xhr) {
      notification.replace(new XWiki.widgets.Notification(getErrorMessage(xhr), 'error'));
      updatePurgeButton(form);
    });
  });

  $(document).on('click', '#purgeNowForm .purge-back', function() {
    const form = $(this).closest('form');
    showPurgeStep(form, false);
    updatePurgeButton(form);
  });

  $(document).on('click', '#purgeNowForm .purge-confirm', function() {
    const modal = $('#purgeNowModal');
    const form = $(this).closest('form');
    const wiki = modal.data('wiki');
    $(this).prop('disabled', true);
    post(getWikiPath(wiki.wikiId) + '/purge', modal.data('purgeData')).done(function(jobIds) {
      if (jobIds.length === 0) {
        // The purges of the selected item types are already running.
        showPurgeStep(form, false);
        form.find('.purge-nothing-started').removeClass('hidden');
        updatePurgeButton(form);
      } else {
        // The history shows the started purges while they run, then their outcome.
        modal.modal('hide');
        openHistory(wiki);
      }
    }).fail(function() {
      form.find('.purge-confirm').prop('disabled', false);
    });
  });

  // The purge history of a wiki.
  let historyRefreshTimeout;

  /**
   * Refresh the history while it shows a purge in progress, more and more rarely, until the deadline.
   */
  const refreshHistory = function(delay, deadline) {
    const liveData = $('#purgeHistory').data('liveData');
    if (!liveData) {
      return;
    }
    liveData.updateEntries().then(() => {
      const modal = $('#purgeHistoryModal');
      const inProgress = liveData.data.data.entries.some(entry => entry.inProgress);
      if (!modal.data('open') || !inProgress) {
        return;
      }
      if (Date.now() + delay > deadline) {
        modal.find('.purge-history-stopped').removeClass('hidden');
      } else {
        historyRefreshTimeout =
          setTimeout(() => refreshHistory(Math.min(delay * 2, maxRefreshDelay), deadline), delay);
      }
    });
  };

  const startHistoryRefresh = function() {
    clearTimeout(historyRefreshTimeout);
    $('#purgeHistoryModal .purge-history-stopped').addClass('hidden');
    refreshHistory(minRefreshDelay, Date.now() + maxRefreshDuration);
  };

  /**
   * Show the purge history of a wiki, from its first page, without the filters chosen for another wiki.
   */
  const openHistory = function(wiki) {
    const modal = $('#purgeHistoryModal');
    setWikiName(modal, wiki.wikiName);
    const liveData = $('#purgeHistory').data('liveData');
    if (liveData) {
      liveData.data.query.source.wikiId = wiki.wikiId;
      liveData.data.query.filters = [];
      liveData.data.query.offset = 0;
    }
    modal.data('open', true).modal('show');
    startHistoryRefresh();
  };

  $(document).on('click', '.purge-history', function() {
    openHistory($(this).data('purge'));
  });

  $(document).on('click', '.purge-history-refresh', startHistoryRefresh);

  // Stop refreshing the history once it is closed, and show the newest purges in the table of the wikis.
  $(document).on('hidden.bs.modal', '#purgeHistoryModal', function() {
    $(this).data('open', false);
    clearTimeout(historyRefreshTimeout);
    refreshLiveData('purgeWikis');
  });

  /**
   * Show the failures of the newest purge of an item type of a wiki.
   */
  const showFailures = function(wikiId, wikiName, type) {
    const modal = $('#purgeFailuresModal');
    const tableBody = modal.find('tbody').empty();
    modal.find('.purge-failures-subtitle, .purge-failures-summary').text('');
    modal.find('.purge-recycle-bin').addClass('hidden');
    modal.modal('show');
    $.getJSON(jsonURL, {data: 'failures', wikiId: wikiId, type: type}).done(function(failures) {
      modal.find('.purge-failures-subtitle').text([wikiName, failures.type, failures.date].join(' \u00b7 '));
      modal.find('.purge-failures-summary').text(failures.summary);
      failures.failures.forEach(failure => {
        const itemCell = $('<td>').text(failure.item);
        tableBody.append($('<tr>').append(itemCell, $('<td>').text(failure.error)));
      });
      // A history has no recycle bin.
      modal.find('.purge-recycle-bin').attr('href', failures.recycleBinURL || '#')
        .toggleClass('hidden', !failures.recycleBinURL);
    }).fail(function() {
      new XWiki.widgets.Notification(l10n.get('loadFailed'), 'error');
    });
  };

  $(document).on('click', '.purge-failures', function(event) {
    event.preventDefault();
    const link = $(this);
    // The links of the history don't hold the wiki name, which is shown by the history modal.
    showFailures(link.data('wikiId'), link.data('wikiName') || $('#purgeHistoryModal').data('wikiName'),
      link.data('type'));
  });

  // Show the failures modal and its backdrop over the history modal. The z-index is computed from the one of the
  // history modal, since the skin extensions of other applications can change the z-index of the modals.
  $(document).on('show.bs.modal', '#purgeFailuresModal', function() {
    const historyModal = $('#purgeHistoryModal.in');
    if (historyModal.length) {
      const zIndex = parseInt(historyModal.css('z-index'), 10);
      const modal = $(this).css('z-index', zIndex + 2);
      // The backdrop is added once the modal starts to show.
      setTimeout(() => $(modal.data('bs.modal').$backdrop).css('z-index', zIndex + 1));
    }
  });

  // Keep the page from scrolling when the failures modal closes over the history modal.
  $(document).on('hidden.bs.modal', '#purgeFailuresModal', function() {
    $(this).css('z-index', '');
    if ($('.purge-modal.in').length > 0) {
      $('body').addClass('modal-open');
    }
  });
});
